import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    import matplotlib.pyplot as plt
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to access URL or retrieve data: {e}")
    if not data or not isinstance(data, (list, dict)):
        raise Exception("Invalid or empty data received.")
    try:
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("Empty data in DataFrame.")
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical data for correlation.")
        ax = sns.heatmap(numeric_df.corr())
        plt.show()
        return df, ax
    except Exception as e:
        raise Exception(f"Error processing data: {e}")

import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    urls = re.findall(r'https?://[^\s]+', myString)
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            domains.add(parsed.netloc.rstrip('.'))

    result = {}
    for domain in domains:
        try:
            api_url = f"http://api.ipapi.com/api/check?access_key={API_KEY}&query={domain}"
            response = requests.get(api_url)
            response.raise_for_status()
            data = response.json()
            result[domain] = data
        except Exception:
            result[domain] = None

    return result

